function open_(id){if(lpf){lpf=false;return}cur=S.chats.find(c=>c.id==id);cur._lim=50;cur.unread=0;lastN=0;$('cav').innerHTML=av(cur.name,38,cur.pic);$('cn').textContent=cur.name;status();$('ms').value='';$('cs2').style.display='none';clr();renderMsgs();go('chat');markRead()}
