function togS(){const s=$('cs2');s.style.display=s.style.display=='none'?'flex':'none';if(s.style.display=='flex')$('ms').focus();else{$('ms').value='';renderMsgs()}}
function hl(t,q){t=esc(t);if(!q)return t;return t.replace(new RegExp('('+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','gi'),'<mark>$1</mark>')}
function renderMsgs(){const q=$('ms').value.trim();
 $('msgs').innerHTML=cur.msgs.filter(x=>!q||(!x.del&&x.m.toLowerCase().includes(q.toLowerCase()))).slice(-(q?300:(cur._lim||50))).map(x=>{
  const r=x.reply&&cur.msgs.find(y=>y.id==x.reply);
  const st=x.me?ic(x.st=='s'?'ck':'ck2',x.st=='r'?'rd':''):'';
  return `<div class="b ${x.me?'me':''} ${x.del?'del':''} ${x.file&&x.file.sk&&!x.del?'sk':''} ${x.poll&&!x.del?'pl':''} ${x.file&&!x.del?(x.file.type.startsWith('image')?'img':x.file.type.startsWith('audio')?'vnb':''):''}" data-id="${x.id}" onclick="menu(event,'${x.id}')">${r?`<div class="q">${r.del?'Message deleted':esc(r.m).slice(0,60)}</div>`:''}${x.del?'Message deleted':x.poll?ph(x):x.file?fh(x.file):ceh(hl(x.m,q),x.ce)}<div class="meta">${x.edited&&!x.del?'edited':''}${st}</div>${rxh(x)}</div>`}).join('');
 $('msgs').scrollTop=q?0:1e9;const bs=$('msgs').children;if(!q&&lastN&&bs.length>lastN&&mo&&!rm)mo(bs[bs.length-1],{opacity:[0,1],transform:['scale(.7) translateY(12px)','scale(1) translateY(0px)']},{type:'spring',stiffness:420,damping:22});lastN=bs.length}
function closeMenu(){if(menuEl){menuEl.remove();menuEl=null}}
function menu(e,id){e.stopPropagation();closeMenu();const x=cur.msgs.find(m=>m.id==id);if(x.del)return;
 const m=document.createElement('div');m.className='menu';
 m.innerHTML=`<div class="rr">${rxRow(id)}</div><div class="ra"><button onclick="rep('${id}')">${ic('reply')}Reply</button><button onclick="cpm('${id}')">${ic('copy')}Copy</button>${x.file&&x.file.url&&x.file.type.startsWith('image')&&!x.file.sk?`<button onclick="closeMenu();openBoard('${id}')">${ic('edit')}Annotate</button>`:''}${x.file&&x.file.sk&&x.file.url?`<button onclick="saveSk('${id}')">${ic('plus')}Add</button>`:''}${x.file&&x.file.url?`<button onclick="sv('${id}')">${ic('dl')}Save</button>`:''}${x.me?`<button onclick="edt('${id}')">${ic('edit')}Edit</button><button onclick="dlt('${id}')">${ic('trash')}Delete</button>`:''}</div>`;
 const b=e.currentTarget,c=$('msgs');c.appendChild(m);m.style.top=Math.max(4,b.offsetTop-96)+'px';m.style.left=Math.min(c.clientWidth-m.offsetWidth-8,Math.max(8,b.offsetLeft))+'px';menuEl=m;if(mo&&!rm)mo(m,{opacity:[0,1],transform:['scale(.8)','scale(1)']},{type:'spring',stiffness:520,damping:24})}
function rep(id){closeMenu();clr();rp=id;const x=cur.msgs.find(m=>m.id==id);$('ctxt').textContent='Replying: '+x.m;$('ctx').classList.add('on');$('inp').focus()}
function edt(id){closeMenu();clr();ed=id;const x=cur.msgs.find(m=>m.id==id);$('ctxt').textContent='Editing message';$('ctx').classList.add('on');$('inp').value=x.m;$('inp').focus()}
function clr(){ed=rp=null;$('ctx').classList.remove('on');if($('inp').value&&!ed)$('inp').value=$('inp').value}
async function dlt(id){closeMenu();const x=cur.msgs.find(m=>m.id==id);x.del=1;x.m='';renderMsgs();tx(cur,{t:'del',id})}
