async function mk(pass){key=null;if(pass){const b=await crypto.subtle.importKey('raw',new TextEncoder().encode(pass),'PBKDF2',0,['deriveKey']);
 key=await crypto.subtle.deriveKey({name:'PBKDF2',salt:new TextEncoder().encode('telewish'),iterations:100000,hash:'SHA-256'},b,{name:'AES-GCM',length:256},0,['encrypt','decrypt'])}}
