const PRE={Light:mkP({bg:'#f3f6ff',tx:'#12151c',ac:'#3b6cf6',ac2:'#7a9bff',card:'#ffffff'}),Dark:mkP({bg:'#0a0d14',tx:'#f2f4f8',ac:'#3b6cf6',ac2:'#6f96ff',card:'#1c2230',gl:.55}),Rose:mkP({bg:'#fff4f7',tx:'#2a1218',ac:'#f0567f',ac2:'#ff93b0',card:'#ffffff'}),Ocean:mkP({bg:'#eafbff',tx:'#0b2530',ac:'#0891b2',ac2:'#4fd1e8',card:'#ffffff'}),Forest:mkP({bg:'#0f1a14',tx:'#e8f5ec',ac:'#25a862',ac2:'#7be0a5',card:'#1c2e24'}),Sunset:mkP({bg:'#fff3ea',tx:'#2b1608',ac:'#f0642f',ac2:'#ffb066',card:'#ffffff'}),Amoled:mkP({bg:'#000000',tx:'#ffffff',ac:'#8b6cf6',ac2:'#c0aeff',card:'#161616',gl:.75,glow:0}),Mocha:mkP({bg:'#241a16',tx:'#f5e9df',ac:'#b87a4b',ac2:'#e8b98f',card:'#3a2a22'}),Lavender:mkP({bg:'#f6f1ff',tx:'#1e1433',ac:'#7c5cfc',ac2:'#b7a2ff',card:'#ffffff'})};
const thCur=()=>S.th||(S.theme=='dark'?PRE.Dark:S.theme=='rose'?PRE.Rose:PRE.Light);
const rgba=(h,a)=>{const n=parseInt(h.slice(1),16);return `rgba(${n>>16},${n>>8&255},${n&255},${a})`};
function xTheme(){const s=document.documentElement.style,t=S.th,on=t&&S.theme=='custom',mx=k=>`color-mix(in srgb,${t.tx} ${k}%,transparent)`;
 const m={'--bg':on&&t.bg,'--tx':on&&t.tx,'--ac2':on&&t.ac2,'--bmt':on&&t.bt,'--glass':on&&rgba(t.card,t.gl),'--edge':on&&mx(16),'--sf':on&&mx(8),'--ln':on&&mx(10),'--mu':on&&`color-mix(in srgb,${t.tx} 55%,${t.bg})`,'--br':on&&t.br+'px','--bl':on&&t.bl+'px'};
 if(on)m['--ac']=t.ac;for(const k in m)m[k]?s.setProperty(k,m[k]):s.removeProperty(k);
 $('app').classList.toggle('nb',!!(on&&!t.glow))}
const _at=applyTheme;applyTheme=function(){_at();xTheme()};
function thSet(k,v){S.th=S.th||{...thCur()};S.th[k]=typeof v=='string'&&v[0]=='#'?v:+v;S.theme='custom';applyTheme();save()}
function thPre(n){S.th={...PRE[n]};S.theme='custom';applyTheme();save();stab('th')}
function thReset(){S.th=null;S.theme=undefined;S.accent=undefined;applyTheme();save();stab('th')}
/* fonts */
const FN=[['System','','' ],['Inter',"Inter,system-ui,sans-serif",'Inter:wght@400;600'],['Poppins',"Poppins,system-ui,sans-serif",'Poppins:wght@400;600'],['Nunito',"Nunito,system-ui,sans-serif",'Nunito:wght@400;700'],['Lora',"Lora,Georgia,serif",'Lora:wght@400;600'],['Merriweather',"Merriweather,Georgia,serif",'Merriweather:wght@400;700'],['JetBrains Mono',"'JetBrains Mono',ui-monospace,monospace",'JetBrains+Mono:wght@400;600'],['Caveat',"Caveat,cursive",'Caveat:wght@400;700'],['Pacifico',"Pacifico,cursive",'Pacifico']];
function loadG(f){if(!f||document.getElementById('gf'+f))return;const l=document.createElement('link');l.id='gf'+f;l.rel='stylesheet';l.href='https://fonts.googleapis.com/css2?family='+f+'&display=swap';document.head.appendChild(l)}
function xFont(){const s=document.documentElement.style;S.ff?s.setProperty('--ff',S.ff):s.removeProperty('--ff');S.fs?s.setProperty('--fs',S.fs+'px'):s.removeProperty('--fs')}
function ffSet(i){S.ff=FN[i][1];loadG(FN[i][2]);xFont();save()}
function fsSet(v){S.fs=+v;xFont();save()}
function fCustom(d){return new FontFace('TWCustom',`url(${d})`).load().then(f=>document.fonts.add(f))}
function ffUp(){const i=document.createElement('input');i.type='file';i.accept='.ttf,.otf,.woff,.woff2';i.onchange=()=>{const f=i.files[0];if(!f)return;if(f.size>1.5e6){alert('Max 1.5 MB');return}const r=new FileReader();r.onload=async()=>{try{await fCustom(r.result);LS('twfont',r.result);S.ff="'TWCustom',system-ui,sans-serif";xFont();save()}catch(e){alert('Invalid font file')}};r.readAsDataURL(f)};i.click()}
function ffReset(){S.ff='';S.fs=0;LS('twfont',null);xFont();save();stab('ft')}
/* wallpaper */
const WPS=[['None',''],['Aurora','linear-gradient(135deg,#7aa2ff,#c68bff 50%,#ff9ec8)'],['Sunset','linear-gradient(160deg,#ffb066,#f0567f 60%,#7c5cfc)'],['Ocean','linear-gradient(160deg,#0ea5e9,#2dd4bf)'],['Forest','linear-gradient(160deg,#134e4a,#2fbf71)'],['Midnight','linear-gradient(160deg,#0f172a,#312e81 70%,#6d28d9)'],['Peach','linear-gradient(160deg,#ffe3d0,#ffc2d1)'],['Dots','radial-gradient(circle,rgba(127,127,127,.3) 1.5px,transparent 2px) 0 0/22px 22px,var(--bg)'],['Grid','linear-gradient(rgba(127,127,127,.16) 1px,transparent 1px) 0 0/28px 28px,linear-gradient(90deg,rgba(127,127,127,.16) 1px,transparent 1px) 0 0/28px 28px,var(--bg)']];
let WPI=null;
function applyWP(){const w=S.wp,v=w&&(w.v=='img'?WPI&&`url(${WPI}) center/cover`:w.v);document.querySelectorAll('.wpl').forEach(e=>{e.style.background=v||'none';e.style.filter=v?`blur(${w.bl||0}px)`:'';e.style.boxShadow=v?`inset 0 0 0 100vmax rgba(0,0,0,${(w.dm||0)/100})`:'none'})}
function wpSet(x,raw){const v=raw?x:WPS[x][1];S.wp=v?{bl:0,dm:0,...S.wp,v}:null;applyWP();save();if(!raw)stab('wp')}
function wpK(k,v){S.wp={...S.wp,[k]:+v};applyWP();save()}
function prep(f,s,fmt,q){return new Promise((ok,no)=>{const u=URL.createObjectURL(f),im=new Image();im.onload=()=>{const k=Math.min(1,s/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.max(1,im.width*k|0);c.height=Math.max(1,im.height*k|0);c.getContext('2d').drawImage(im,0,0,c.width,c.height);URL.revokeObjectURL(u);ok(c.toDataURL(fmt,q))};im.onerror=()=>no();im.src=u})}
function pick(cb,multi){const i=document.createElement('input');i.type='file';i.accept='image/*';i.multiple=!!multi;i.onchange=()=>i.files.length&&cb([...i.files]);i.click()}
function wpPhoto(){pick(async f=>{try{WPI=await prep(f[0],1400,'image/jpeg',.72);LS('twwp',WPI);S.wp={bl:0,dm:15,...S.wp,v:'img'};applyWP();save();stab('wp')}catch(e){alert('Could not read image')}})}
/* packs */
let PK=[];try{PK=JSON.parse(LS('twpk')||'[]')}catch(e){}
[['e','My emoji','emoji'],['s','My stickers','sticker']].forEach(([id,name,type])=>{if(!PK.find(p=>p.id==id))PK.push({id,name,type,items:[]})});
const spk=()=>LS('twpk',JSON.stringify(PK));
const allE=()=>PK.filter(p=>p.type=='emoji').flatMap(p=>p.items);
const cd=n=>{const e=allE().find(x=>x.n==n);return e&&e.d};
const okImg=d=>typeof d=='string'&&d.length<400000&&/^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/=]+$/.test(d);
const cn=s=>String(s).toLowerCase().replace(/\.[a-z0-9]+$/,'').replace(/[^a-z0-9_]+/g,'_').replace(/^_+|_+$/g,'').slice(0,24)||'emoji';
const uniq=n=>{let b=n.slice(0,20),k=b,i=1;const ex=allE().map(e=>e.n);while(ex.includes(k))k=b+(++i);return k};
function usedCE(t){const o={};let n=0;(t.match(/:([a-z0-9_]{1,24}):/g)||[]).forEach(s=>{const k=s.slice(1,-1),d=cd(k);if(d&&d.length<40000&&n<20){o[k]=d;n++}});return n?o:undefined}
function cl(o){if(!o||typeof o!='object')return;const r={};Object.keys(o).slice(0,20).forEach(k=>{if(/^[a-z0-9_]{1,24}$/.test(k)&&okImg(o[k]))r[k]=o[k]});return r}
function ceh(h,ce){return h.replace(/:([a-z0-9_]{1,24}):/g,(m,n)=>{const d=(ce&&ce[n])||cd(n);return d&&okImg(d)?`<img class="ce" alt="${m}" src="${d}">`:m})}
function rci(x,k){if(k[0]=='u')return `<span class="ue">${esc(k.slice(2))}</span>`;const d=(x.rcd&&x.rcd[k])||cd(k.slice(2));return d&&okImg(d)?`<img class="ce" src="${d}">`:':'+esc(k.slice(2))+':'}
async function addItems(pid,fs){const p=PK.find(x=>x.id==pid),em=p.type=='emoji';for(const f of fs.slice(0,60)){try{const d=await prep(f,em?72:256,em?'image/png':'image/webp',.85);p.items.push({n:em?uniq(cn(f.name)):cn(f.name)+p.items.length,d})}catch(e){}}spk();stab(stk)}
const addTo=pid=>pick(f=>addItems(pid,f),1);
function delIt(pid,i){PK.find(p=>p.id==pid).items.splice(i,1);spk();stab(stk)}
function renIt(pid,i){const p=PK.find(x=>x.id==pid);if(p.type!='emoji')return;dlg('Emoji name (used as :name:)','Save',v=>{v=cn(v);if(allE().some((e,j)=>e.n==v&&e!==p.items[i]))v=uniq(v);p.items[i].n=v;spk();stab(stk)},p.items[i].n)}
function newPk(t){dlg('New pack name','Create',v=>{PK.push({id:uid(),name:v.trim().slice(0,40)||'New pack',type:t,items:[]});spk();stab(stk)},'')}
function renPk(id){const p=PK.find(x=>x.id==id);dlg('Rename pack','Save',v=>{p.name=v.trim().slice(0,40)||p.name;spk();stab(stk)},p.name)}
function delPk(id){dlg('Delete this pack?','Delete',()=>{PK=PK.filter(p=>p.id!=id);spk();stab(stk)})}
async function dlJSON(fn,o,sh){const f=new File([JSON.stringify(o)],fn,{type:'application/json'});
 if(sh&&navigator.canShare&&navigator.canShare({files:[f]})){try{await navigator.share({files:[f],title:fn});return}catch(e){if(e.name=='AbortError')return}}
 const a=document.createElement('a');a.href=URL.createObjectURL(f);a.download=fn;document.body.appendChild(a);a.click();a.remove()}
const pkObj=id=>{const p=PK.find(x=>x.id==id);return [cn(p.name)+'.twpack.json',{kind:'pack',v:1,name:p.name,type:p.type,by:S.name,items:p.items.map(i=>({n:i.n,d:i.d}))}]};
const expPk=id=>dlJSON(...pkObj(id));const shPk=id=>dlJSON(...pkObj(id),1);
const msg=t=>{const e=$('ims');if(e)e.textContent=t};
let CAT=[];
async function toD(d,base,s){if(okImg(d))return d;if(typeof d!='string')throw 0;const r=await fetch(new URL(d,base));return prep(await r.blob(),s,s>100?'image/webp':'image/png',.85)}
async function impObj(o,base){
 if(o.kind=='theme'){S.th={...PRE.Light,...o.th};S.theme='custom';if(typeof o.ff=='string')S.ff=o.ff;applyTheme();xFont();save();stab('th');msg('Theme applied');return}
 if(o.kind=='catalog'&&Array.isArray(o.packs)){CAT=o.packs.slice(0,30).map(p=>String(new URL(p.url,base)));$('ic').innerHTML=o.packs.slice(0,30).map((p,i)=>`<div class="rw"><span>${esc(p.name||'Pack')} <small class="hint">${esc(p.type||'')}</small></span><button class="btn g" style="width:auto;margin:0;padding:8px 14px" onclick="impUrl(CAT[${i}])">Add</button></div>`).join('');msg('Pick a pack to add');return}
 if(o.kind!='pack'||!Array.isArray(o.items))throw 0;
 const t=o.type=='sticker'?'sticker':'emoji',em=t=='emoji',items=[];msg('Importing…');
 for(const it of o.items.slice(0,em?200:60)){try{const d=await toD(it.d||it.url,base,em?72:256);items.push({n:em?uniq(cn(it.n||'emoji')):cn(it.n||'s')+items.length,d});if(em)PK.find(p=>p.id=='e').items.length}catch(e){}}
 if(!items.length)throw 0;
 const np={id:uid(),name:String(o.name||'Imported').slice(0,40),type:t,items};
 if(em){const ex=new Set(allE().map(e=>e.n));np.items.forEach(i=>{let k=i.n,j=1;while(ex.has(k))k=i.n.slice(0,20)+(++j);i.n=k;ex.add(k)})}
 PK.push(np);spk();stab(em?'em':'sk');msg(`Added “${np.name}” (${items.length})`)}
async function impUrl(u){u=String(u||$('iu').value).trim();if(!u)return;msg('Fetching…');try{const r=await fetch(u);if(!r.ok)throw 0;await impObj(await r.json(),u)}catch(e){msg('Could not import. Check the URL, and that your site allows CORS (Access-Control-Allow-Origin: *).')}}
function impFile(){const i=document.createElement('input');i.type='file';i.accept='.json,.twpack,.twtheme,application/json';i.onchange=async()=>{try{await impObj(JSON.parse(await i.files[0].text()),location.href)}catch(e){msg('Invalid file')}};i.click()}
const SITES=[['OpenMoji','https://openmoji.org/library/','Open-source emoji, free PNG/SVG downloads (CC BY-SA)'],['Emoji.gg','https://emoji.gg/','Community custom emoji, download as PNG'],['Slackmojis','https://slackmojis.com/','Huge library of custom emoji, PNG/GIF'],['Microsoft Fluent Emoji','https://github.com/microsoft/fluentui-emoji','Full emoji set on GitHub (MIT)'],['Google Noto Emoji','https://github.com/googlefonts/noto-emoji','Full emoji set on GitHub (open licence)'],['Sticker.ly','https://sticker.ly/','Sticker packs (WhatsApp/Telegram), mostly via their app'],['GetStickerPack','https://getstickerpack.com/','WhatsApp/Telegram sticker packs']];
const impUI=()=>`<div class="pkc"><b>Import packs</b><p class="hint">Works with .zip files, WhatsApp .wastickers, a folder of images, or a .twpack.json. Drag and drop onto this page, or use the buttons.</p><button class="btn" onclick="impFile()">Import files (zip, images, pack)</button><label>Or from a link (your own site)</label><input type="text" id="iu" placeholder="https://yoursite.com/packs/cats.twpack.json"><button class="btn g" onclick="impUrl()">Import from link</button><div id="ic"></div><p class="hint" id="ims"></p></div><div class="pkc"><b>Where to find packs</b><p class="hint">Download a zip or images from any of these (or any site you like), then import them here. Check each pack's licence before sharing it.</p><div class="sites">${SITES.map(([n,u,d])=>`<a href="${u}" target="_blank" rel="noopener noreferrer"><b>${n}</b><small>${d}</small></a>`).join('')}</div></div>`;
function packsUI(t){const em=t=='emoji';return `<p class="hint">${em?'Add images, then type <b>:name:</b> in a message or long-press a bubble to react with them. Friends see them even without your pack.':'Tap a sticker in the chat picker to send it. Received stickers can be saved to your pack.'}</p>`+PK.filter(p=>p.type==t).map(p=>`<div class="pkc"><div class="rw"><div><b>${esc(p.name)}</b><div class="hint">${p.items.length} items</div></div><div class="pa"><button class="ib" onclick="addTo('${p.id}')" data-i="plus"></button><button class="ib" onclick="expPk('${p.id}')" data-i="dl"></button><button class="ib" onclick="shPk('${p.id}')" data-i="share"></button>${p.id.length>1?`<button class="ib" onclick="renPk('${p.id}')" data-i="edit"></button><button class="ib" onclick="delPk('${p.id}')" data-i="trash"></button>`:''}</div></div><div class="pg${em?'':' lg'}">${p.items.map((e,i)=>`<div class="it" onclick="renIt('${p.id}',${i})"><img src="${e.d}"><i class="x" onclick="event.stopPropagation();delIt('${p.id}',${i})">${ic('x')}</i>${em?`<small>${e.n}</small>`:''}</div>`).join('')||'<div class="hint">Empty. Tap + to add images.</div>'}</div></div>`).join('')+`<button class="btn g" onclick="newPk('${t}')">${ic('plus')}New pack</button>`+impUI()}
