const UE='😀😂🥹😍😘😎🤔😴😭😡🥳🤯👍👎👏🙏💪🔥✨❤️💜💙🎉🌈☕🍕🐱🐶🌸🌙⭐💯✅❌👀🙌🤝😅😉😇🤗🥰'.match(/\p{Extended_Pictographic}\uFE0F?/gu),ins=t=>{const i=$('inp'),a=i.selectionStart??i.value.length;i.value=i.value.slice(0,a)+t+i.value.slice(i.selectionEnd??a);i.focus();const p=a+t.length;i.setSelectionRange(p,p)};
let pkt='e';
