function drawPk(){const sp=PK.filter(p=>p.type=='sticker'&&p.items.length);let h=`<div class="tabs sc"><button class="${pkt=='e'?'on':''}" onclick="pkt='e';drawPk()">${ic('happy')}</button>${sp.map(p=>`<button class="${pkt==p.id?'on':''}" onclick="pkt='${p.id}';drawPk()"><img class="ce" src="${p.items[0].d}"></button>`).join('')}<button onclick="openStudio('sk')">${ic('plus')}</button></div>`;
 if(pkt=='e'||!sp.find(p=>p.id==pkt)){pkt='e';h+=`<div class="pg">${allE().map(e=>`<button class="it" title=":${e.n}:" onclick="ins(':${e.n}:')"><img src="${e.d}"></button>`).join('')}${UE.map(c=>`<button class="it" data-c="${c}" onclick="ins(this.dataset.c)">${c}</button>`).join('')}</div>`}
 else{const p=sp.find(x=>x.id==pkt);h+=`<div class="pg lg">${p.items.map((e,i)=>`<button class="it" onclick="sendSk('${p.id}',${i})"><img src="${e.d}"></button>`).join('')}</div>`}
 $('pk').innerHTML=h;icons()}
