/* smarter pack import */
async function impFiles(fs){fs=[...fs];const t=stk=='sk'?'sticker':'emoji';msg('Reading…');try{
 const js=fs.find(f=>/\.(json|twpack|twtheme)$/i.test(f.name));if(js){await impObj(JSON.parse(await js.text()),location.href);return}
 const imgs=[];let name='Imported';
 for(const f of fs){if(/\.(zip|wastickers)$/i.test(f.name)){const z=await JSZip.loadAsync(f);name=f.name.replace(/\.[^.]+$/,'');for(const e of Object.values(z.files)){const m=e.name.match(/\.(png|webp|jpe?g|gif)$/i);if(!e.dir&&m&&!/tray|icon/i.test(e.name))imgs.push(new File([await e.async('blob')],e.name.split('/').pop(),{type:'image/'+m[1].toLowerCase().replace('jpg','jpeg')}))}}else if(f.type.startsWith('image/'))imgs.push(f)}
 if(!imgs.length)throw 0;const p={id:uid(),name:name.slice(0,40),type:t,items:[]};PK.push(p);await addItems(p.id,imgs);msg(`Added “${p.name}” (${p.items.length})`)}catch(e){msg('Could not read those files. Try a .zip, .wastickers, images, or a .twpack.json.')}}
function impFile(){const i=document.createElement('input');i.type='file';i.multiple=true;i.accept='.json,.twpack,.twtheme,.zip,.wastickers,image/*';i.onchange=()=>i.files.length&&impFiles(i.files);i.click()}
async function impUrl(u){u=String(u||$('iu').value).trim();if(!u)return;msg('Fetching…');try{const r=await fetch(u);if(!r.ok)throw 0;const ct=r.headers.get('content-type')||'';if(/json|text\/plain/.test(ct)||/\.json(\?|$)/i.test(u))return await impObj(await r.json(),u);const b=await r.blob();await impFiles([new File([b],u.split('?')[0].split('/').pop()||'pack',{type:b.type})])}catch(e){msg('Could not import from that link. Many sites block direct downloads, so download the zip or images first, then use “Import files” (or drop them here).')}}
addEventListener('dragover',e=>{if($('studio').classList.contains('on'))e.preventDefault()});addEventListener('drop',e=>{if(!$('studio').classList.contains('on')||(stk!='em'&&stk!='sk'))return;e.preventDefault();impFiles(e.dataTransfer.files)});

