/* --- connection info --- */
async function nInfo(c){if(!c.pc||!c.live)return null;try{const r=await c.pc.getStats(),m={};let pr=null;r.forEach(x=>{m[x.id]=x;if(x.type=='transport'&&x.selectedCandidatePairId)pr=m[x.selectedCandidatePairId]||r.get(x.selectedCandidatePairId)});
 if(!pr)r.forEach(x=>{if(x.type=='candidate-pair'&&(x.selected||x.nominated&&x.state=='succeeded'))pr=x});if(!pr)return null;
 const l=r.get(pr.localCandidateId),q=r.get(pr.remoteCandidateId),t=[l&&l.candidateType,q&&q.candidateType];
 const kind=t.includes('relay')?'Relayed':t.every(x=>x=='host')?'Direct · same network':'Direct · over internet';
 return{kind,rtt:pr.currentRoundTripTime!=null?Math.round(pr.currentRoundTripTime*1000):null,proto:(l&&l.protocol||'').toUpperCase()}}catch(e){return null}}
