async function nShare(L){const t=N.t;if(!t||!t.f)return;const f=t.f,buf=new Uint8Array(await f.arrayBuffer()),CH=12000,n=Math.ceil(buf.length/CH)||1;
 await Promise.all(L.map(async c=>{if(N.have[c.id]===t.id||N.prog[c.id]>=0&&N.prog[c.id]<100)return;N.prog[c.id]=0;
  await tx(c,{t:'nmus',id:t.id,name:t.name,size:f.size,n,type:f.type||'audio/mpeg'});
  for(let i=0;i<n;i++){if(!c.live||N.t!==t)return;await tx(c,{t:'nmc',id:t.id,i,d:b64(buf.subarray(i*CH,(i+1)*CH))});N.prog[c.id]=Math.round((i+1)/n*100);
   if(c.dc.bufferedAmount>1e6)await new Promise(r=>{const w=()=>c.dc.bufferedAmount<2e5?r():setTimeout(w,60);w()})}}))}
