/* ---- custom sounds (audio files live in IndexedDB, names in CX.snd) ---- */
const SNDS=[['s','Message sent'],['r','Message received'],['x','Reaction added'],['n','Pop-up notification'],['ci','Incoming call ringtone'],['co','Outgoing call tone'],['ce','Call ended'],['tap','Button tap']],SB={};
